    pass


class _ModelFieldDef:
    def __init__(self, default=..., default_factory=None):
        self.default = default
        self.default_factory = default_factory

    @property
    def required(self):
        return self.default is ... and self.default_factory is None

    def get_default(self):
        if self.default_factory is not None:
            return self.default_factory()
        return None if self.required else self.default


def Field(default=..., **kwargs):
    return _ModelFieldDef(default, kwargs.get("default_factory"))


class BaseModel:
    __fields__ = {}

    class Config:
        json_encoders = {}

    def __init__(self, **data):
        object.__setattr__(self, "__fields_set__", set(data.keys()))
        for name, f in self.__class__.__fields__.items():
            if name in data:
                setattr(self, name, data[name])
            elif not f.required:
                setattr(self, name, f.get_default())

    def dict(
        self,
        *,
        include=None,
        exclude=None,
        by_alias=False,
        exclude_unset=False,
        exclude_none=False,
        exclude_defaults=False,
        skip_defaults=None,
    ):
        out = {}
        for name, f in self.__class__.__fields__.items():
            value = getattr(self, name)
            if include is not None and name not in include:
                continue
            if exclude is not None and name in exclude:
                continue
            if (exclude_unset or skip_defaults) and name not in self.__fields_set__:
                continue
            if exclude_none and value is None:
                continue
            if exclude_defaults and not f.required and value == f.get_default():
                continue
            out[name] = value
        return out


def create_model(name, __base__=None, **kwargs):
    base = __base__ or BaseModel
    return type(name, (base,), {"__fields__": dict(base.__fields__)})


