# AST-level signature consistency check (mirrors tests/test_operations_signatures.py)
import ast, sys

def get_params(filepath, classnames):
    tree = ast.parse(open(filepath).read())
    out = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef) and node.name in classnames:
            for item in node.body:
                if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    args = item.args
                    params = {}
                    allargs = args.args + args.kwonlyargs
                    defaults = [None] * (len(allargs) - len(args.defaults) - len(args.kw_defaults)) + list(args.defaults)
                    # kwonly defaults are aligned with kwonlyargs
                    kwdefs = dict(zip([a.arg for a in args.kwonlyargs], args.kw_defaults))
                    for a in args.kwonlyargs:
                        ann = ast.unparse(a.annotation) if a.annotation else None
                        d = kwdefs.get(a.arg)
                        params[a.arg] = (ann, ast.unparse(d) if d is not None else None)
                    out.setdefault(node.name, {})[item.name] = params
    return out

